return $input.all().map(item => {
  const p = item.json;
  const raw = p.raw_body ?? p.body;
  const signature = p.signature ?? p.headers?.['x-notion-signature'];
  // NEVER re-serialize an already-parsed JSON object: HMAC signs exact bytes.
  if (typeof raw !== 'string' || !raw.length || raw.length > 60000) {
    throw new Error('RAW_BODY_REQUIRED: preserve Notion request body exactly');
  }
  if (typeof signature !== 'string' || !/^sha256=[0-9a-f]{64}$/i.test(signature)) {
    throw new Error('NOTION_SIGNATURE_REQUIRED');
  }
  return { json: { raw_body: raw, signature } };
});
